mapper.select:
SELECT CURDATE() AS statDate, o.store_id AS storeId, s.name AS storeName, COUNT(*) AS totalOrderCount, COUNT(CASE WHEN o.status IN ('PAID', 'PENDING_VERIFICATION', 'COMPLETED') THEN 1 END) AS paidOrderCount, COALESCE(SUM(o.total_product_price), 0) AS totalSalesAmount, COALESCE(SUM(CASE WHEN o.status IN ('PAID', 'PENDING_VERIFICATION', 'COMPLETED') THEN o.final_paid_price ELSE 0 END), 0) AS realPayAmount, COUNT(CASE WHEN o.status IN ('REFUNDING', 'REFUNDED', 'CANCELLED') THEN 1 END) AS refundOrderCount, COALESCE(SUM(CASE WHEN o.status = 'REFUNDED' THEN o.final_paid_price ELSE 0 END), 0) AS refundAmount, 0 AS visitorCount, 0 AS pageViewCount, CASE WHEN COUNT(CASE WHEN o.status IN ('PAID', 'PENDING_VERIFICATION', 'COMPLETED') THEN 1 END) > 0 THEN ROUND( COALESCE(SUM(CASE WHEN o.status IN ('PAID', 'PENDING_VERIFICATION', 'COMPLETED') THEN o.final_paid_price ELSE 0 END), 0) / COUNT(CASE WHEN o.status IN ('PAID', 'PENDING_VERIFICATION', 'COMPLETED') THEN 1 END), 2) ELSE 0 END AS avgOrderValue FROM orders o LEFT JOIN stores s ON o.store_id = s.id WHERE DATE(o.created_time) = CURDATE() AND o.is_deleted = 0
AND o.store_id = #{storeId}
AND o.merchant_id = #{merchantId}
GROUP BY o.store_id, s.name

SELECT oi.product_sku_id AS skuId, oi.product_id AS productId, oi.product_name AS productName, oi.sku_name AS skuSpec, SUM(oi.quantity) AS salesQuantity, SUM(oi.final_price) AS salesAmount, RANK() OVER (ORDER BY SUM(oi.final_price) DESC) AS `rank` FROM order_items oi INNER JOIN orders o ON oi.order_id = o.id WHERE DATE(o.created_time) = CURDATE() AND o.status IN ('PAID', 'PENDING_VERIFICATION', 'COMPLETED') AND o.is_deleted = 0 AND oi.is_deleted = 0
AND o.store_id = #{storeId}
AND o.merchant_id = #{merchantId}
GROUP BY oi.product_sku_id, oi.product_id, oi.product_name, oi.sku_name
ORDER BY salesAmount DESC LIMIT #{topN}

SELECT g.sku_id AS skuId, g.product_name AS productName, g.sku_spec AS skuSpec, g.category_id AS categoryId, c.name AS categoryName,
SUM(g.sales_quantity) AS currentSalesQty, SUM(g.sales_amount) AS currentSalesAmount,
COALESCE(lw.lastWeekSalesQty, 0) AS lastWeekSalesQty, COALESCE(lw.lastWeekSalesAmount, 0) AS lastWeekSalesAmount,
CASE WHEN COALESCE(lw.lastWeekSalesQty, 0) > 0 THEN ROUND((SUM(g.sales_quantity) - lw.lastWeekSalesQty) / lw.lastWeekSalesQty * 100, 2) ELSE NULL END AS salesQtyChangeRate, CASE WHEN COALESCE(lw.lastWeekSalesAmount, 0) > 0 THEN ROUND((SUM(g.sales_amount) - lw.lastWeekSalesAmount) / lw.lastWeekSalesAmount * 100, 2) ELSE NULL END AS salesAmountChangeRate,
CASE WHEN lw.lastWeekSalesQty IS NULL THEN 'FLAT' WHEN SUM(g.sales_quantity) > lw.lastWeekSalesQty THEN 'UP' WHEN SUM(g.sales_quantity) < lw.lastWeekSalesQty THEN 'DOWN' ELSE 'FLAT' END AS trend FROM report_goods_sales_daily g LEFT JOIN product_categories c ON g.category_id = c.id LEFT JOIN ( SELECT sku_id, SUM(sales_quantity) AS lastWeekSalesQty, SUM(sales_amount) AS lastWeekSalesAmount FROM report_goods_sales_daily WHERE stat_date BETWEEN DATE_SUB(#{startDate}, INTERVAL 7 DAY) AND DATE_SUB(#{endDate}, INTERVAL 7 DAY) AND is_deleted = 0
AND store_id = #{storeId}
AND merchant_id = #{merchantId}
GROUP BY sku_id ) lw ON g.sku_id = lw.sku_id WHERE g.stat_date BETWEEN #{startDate} AND #{endDate} AND g.is_deleted = 0
AND g.store_id = #{storeId}
AND g.merchant_id = #{merchantId}
AND g.category_id = #{categoryId}
GROUP BY g.sku_id, g.product_name, g.sku_spec, g.category_id, c.name, lw.lastWeekSalesQty, lw.lastWeekSalesAmount ORDER BY currentSalesAmount DESC

SELECT u.stat_date AS statDate, u.store_id AS storeId, u.merchant_id AS merchantId, u.new_user_count AS newUserCount, u.active_user_count AS activeUserCount, u.repurchase_rate AS repurchaseRate,
CASE WHEN uw.new_user_count IS NOT NULL AND uw.new_user_count > 0 THEN ROUND((u.new_user_count - uw.new_user_count) / uw.new_user_count * 100, 2) ELSE NULL END AS newUserWow, CASE WHEN uw.active_user_count IS NOT NULL AND uw.active_user_count > 0 THEN ROUND((u.active_user_count - uw.active_user_count) / uw.active_user_count * 100, 2) ELSE NULL END AS activeUserWow, CASE WHEN uw.repurchase_rate IS NOT NULL THEN ROUND(u.repurchase_rate - uw.repurchase_rate, 2) ELSE NULL END AS repurchaseRateWow,
CASE WHEN um.new_user_count IS NOT NULL AND um.new_user_count > 0 THEN ROUND((u.new_user_count - um.new_user_count) / um.new_user_count * 100, 2) ELSE NULL END AS newUserMom, CASE WHEN um.active_user_count IS NOT NULL AND um.active_user_count > 0 THEN ROUND((u.active_user_count - um.active_user_count) / um.active_user_count * 100, 2) ELSE NULL END AS activeUserMom, CASE WHEN um.repurchase_rate IS NOT NULL THEN ROUND(u.repurchase_rate - um.repurchase_rate, 2) ELSE NULL END AS repurchaseRateMom FROM report_user_consumption u LEFT JOIN report_user_consumption uw ON u.store_id = uw.store_id AND u.merchant_id = uw.merchant_id AND uw.stat_date = DATE_SUB(u.stat_date, INTERVAL 7 DAY) LEFT JOIN report_user_consumption um ON u.store_id = um.store_id AND u.merchant_id = um.merchant_id AND um.stat_date = DATE_SUB(u.stat_date, INTERVAL 1 MONTH) WHERE u.stat_date BETWEEN #{startDate} AND #{endDate} AND u.is_deleted = 0
AND u.store_id = #{storeId}
AND u.merchant_id = #{merchantId}
ORDER BY u.stat_date DESC
